-- 000068_report_templates_v2.up.sql
-- 1) Perbaiki template bawaan yang rusak: migrasi 000066 menyisipkan
--    literal "JSON_ARRAY(...)" sebagai teks (bukan JSON valid), sehingga
--    template bawaan tidak pernah bisa dimuat.
-- 2) Naikkan skema layout bawaan ke v2 (rows/columns + density controls).
-- Template buatan pengguna tetap dimigrasi otomatis di runtime oleh
-- deserializeReportDocument().

UPDATE report_templates
SET layout_json = '{"schemaVersion":2,"paperSize":"A4","orientation":"portrait","showFooter":true,"density":"normal","margin":{"top":36,"bottom":45,"left":40,"right":40},"typography":{"baseFontSize":9,"tableFontSize":8,"lineHeight":1.4,"rowPadding":4,"blockGap":8},"headerRepeat":true,"pages":[{"id":"p1","name":"Laporan Tabungan","useHeader":true,"rows":[{"id":"r1","columns":[{"id":"c1","widthPct":100,"blocks":[{"instanceId":"b-kop","blockId":"kop_laporan","enabled":true,"data":{"variant":"pemerintah"}},{"instanceId":"b-judul","blockId":"judul_laporan","enabled":true,"data":{"judul":"LAPORAN REKAPITULASI TABUNGAN SISWA","subjudul":"Periode Cetak Laporan Tabungan"}},{"instanceId":"b-summary","blockId":"ringkasan_kpi","enabled":true,"data":{"items":[{"label":"Total Setoran","key":"total_setoran","format":"rupiah"},{"label":"Total Penarikan","key":"total_penarikan","format":"rupiah"},{"label":"Saldo Akhir","key":"saldo_akhir","format":"rupiah"}]}},{"instanceId":"b-table","blockId":"tabel_laporan","enabled":true,"data":{"title":"","showFooter":"auto","sections":[],"columns":[{"key":"no","label":"No","width":30,"align":"center","format":"text"},{"key":"nisn","label":"NISN","width":80,"align":"center","format":"text"},{"key":"nama","label":"Nama Siswa","width":160,"align":"left","format":"text"},{"key":"kelas","label":"Kelas","width":60,"align":"center","format":"text"},{"key":"total_setoran","label":"Total Setoran","width":110,"align":"right","format":"rupiah","autoSum":true},{"key":"total_penarikan","label":"Total Penarikan","width":110,"align":"right","format":"rupiah","autoSum":true},{"key":"saldo_akhir","label":"Saldo Akhir","width":110,"align":"right","format":"rupiah","autoSum":true}]}},{"instanceId":"b-ttd","blockId":"tanda_tangan","enabled":true,"data":{"jabatan":"Kepala Sekolah","show_stamp":"true"}}]}]}]}]}'
WHERE code = 'RPT_TABUNGAN_REKAP';

UPDATE report_templates
SET layout_json = '{"schemaVersion":2,"paperSize":"A4","orientation":"landscape","showFooter":true,"density":"normal","margin":{"top":36,"bottom":45,"left":40,"right":40},"typography":{"baseFontSize":9,"tableFontSize":8,"lineHeight":1.4,"rowPadding":4,"blockGap":8},"headerRepeat":true,"pages":[{"id":"p1","name":"Laporan Inventaris","useHeader":true,"rows":[{"id":"r1","columns":[{"id":"c1","widthPct":100,"blocks":[{"instanceId":"b-kop","blockId":"kop_laporan","enabled":true,"data":{"variant":"pemerintah"}},{"instanceId":"b-judul","blockId":"judul_laporan","enabled":true,"data":{"judul":"LAPORAN REKAPITULASI ASET DAN INVENTARIS SEKOLAH","subjudul":"Data Kondisi dan Lokasi Barang Aset"}},{"instanceId":"b-summary","blockId":"ringkasan_kpi","enabled":true,"data":{"items":[{"label":"Total Unit Aset","key":"total_unit","format":"number"},{"label":"Kondisi Baik","key":"kondisi_baik","format":"number"},{"label":"Rusak Berat","key":"rusak_berat","format":"number"}]}},{"instanceId":"b-table","blockId":"tabel_laporan","enabled":true,"data":{"title":"","showFooter":"auto","sections":[],"columns":[{"key":"no","label":"No","width":30,"align":"center","format":"text"},{"key":"kode_barang","label":"Kode Barang","width":100,"align":"center","format":"text"},{"key":"nama_barang","label":"Nama Barang / Spesifikasi","width":200,"align":"left","format":"text"},{"key":"kategori","label":"Kategori","width":100,"align":"left","format":"text"},{"key":"lokasi","label":"Lokasi Ruangan","width":120,"align":"left","format":"text"},{"key":"jumlah","label":"Jumlah","width":60,"align":"center","format":"number","autoSum":true},{"key":"kondisi","label":"Kondisi","width":80,"align":"center","format":"text"}]}},{"instanceId":"b-ttd","blockId":"tanda_tangan_ganda","enabled":true,"data":{"kiri_jabatan":"Pengelola Inventaris","kanan_jabatan":"Kepala Sekolah","show_stamp":"true"}}]}]}]}]}'
WHERE code = 'RPT_INVENTARIS_ASET';
